  async function settings(el){el.innerHTML=heading(B.t("ui.admin.f6587bbc11","YOUR PRIVATE OFFICE"),B.t("ui.admin.90ad346d41","Account & security."),B.t("ui.admin.signinIntro","How you sign in to this workspace."))+`<section class="card"><div class="card-head"><h2>${B.h("ui.admin.signinTitle","Signing in")}</h2></div><div class="card-body"><p style="margin-bottom:12px">${B.h("ui.admin.signinEmail","You’re signed in as {email}.",{email:user.email})}</p><p class="note" style="margin-bottom:20px">${B.h("ui.admin.signinNote","There’s no password. Each time you sign in, a 6-digit code is emailed to this address. You stay signed in on this device until you sign out.")}</p><button type="button" class="btn" id="settings-logout">${B.h("ui.shared.dc1649a16c","Sign out")}</button></div></section>`+footer();el.querySelector('#settings-logout').onclick=()=>document.querySelector('#logout').click();}
  async function render(){const id=++generation;const next=location.hash.slice(1)||'overview';section=['overview','applications','members','partners','content','media','analytics','requests','settings'].includes(next)?next:'overview';shell(user,section);const el=document.querySelector('#page');el.innerHTML=`<p class="note">${B.h("ui.admin.786d09b6e3","Opening your workspace…")}</p>`;try{await ({overview:()=>overview(el),applications:()=>crm(el,null),members:()=>crm(el,'member'),partners:()=>crm(el,'partner'),content:()=>content(el),media:()=>library(el),analytics:()=>analytics(el),requests:()=>requests(el),settings:()=>settings(el)})[section]();if(id===generation)W.focusView(el);}catch(e){if(id===generation)el.innerHTML=`<div class="message error" role="alert">${esc(e.message)}</div><button class="btn" onclick="location.reload()">${B.h("ui.admin.042c862e44","Try again")}</button>`;}}
